body:
It looks like this might be a language server issue, actually.  Looks like the `completionItem/resolve` response doesn't properly give a textEdit.  The request and two communications from the language server look like this, when formatted:

```json
-> {
  "jsonrpc": "2.0",
  "method": "completionItem/resolve",
  "params": {
    "data": {
      "filePath": "/tmp/tmp.ZmHxbsplID/src/example.py",
      "position": {
        "character": 2,
        "line": 3
      },
      "symbolLabel": "Uppercase",
      "workspacePath": "/tmp/tmp.ZmHxbsplID"
    },
    "kind": 7,
    "label": "Uppercase",
    "sortText": "09.9999.Uppercase"
  },
  "id": 13
}
<- {
  "jsonrpc": "2.0",
  "id": 13,
  "result": {
    "data": {
      "filePath": "/tmp/tmp.ZmHxbsplID/src/example.py",
      "position": {
        "character": 2,
        "line": 3
      },
      "symbolLabel": "Uppercase",
      "workspacePath": "/tmp/tmp.ZmHxbsplID"
    },
    "kind": 7,
    "label": "Uppercase",
    "sortText": "09.9999.Uppercase",
    "documentation": {
      "kind": "plaintext",
      "value": "class Uppercase()"
    }
  }
}
<- {
  "data": {
    "filePath": "/tmp/tmp.ZmHxbsplID/src/example.py",
    "position": {
      "character": 2,
      "line": 3
    },
    "symbolLabel": "Uppercase",
    "workspacePath": "/tmp/tmp.ZmHxbsplID"
  },
  "documentation": {
    "kind": "plaintext",
    "value": "class Uppercase()"
  },
  "kind": 7,
  "label": "Uppercase",
  "sortText": "09.9999.Uppercase"
}
```

But the equivalent from rust-analyzer, for instance, look like this:

```json
-> {
  "jsonrpc": "2.0",
  "method": "textDocument/didChange",
  "params": {
    "contentChanges": [
      {
        "range": {
          "end": {
            "character": 6,
            "line": 4
          },
          "start": {
            "character": 4,
            "line": 4
          }
        },
        "text": "Uppercase"
      }
    ],
    "textDocument": {
      "uri": "file:///tmp/tmp.a2fOsJD8aq/src/main.rs",
      "version": 27
    }
  }
}
-> {
  "jsonrpc": "2.0",
  "method": "completionItem/resolve",
  "params": {
    "additionalTextEdits": [],
    "deprecated": false,
    "filterText": "Uppercase",
    "kind": 22,
    "label": "Uppercase",
    "preselect": true,
    "sortText": "ffffffef",
    "textEdit": {
      "insert": {
        "end": {
          "character": 6,
          "line": 4
        },
        "start": {
          "character": 4,
          "line": 4
        }
      },
      "newText": "Uppercase",
      "replace": {
        "end": {
          "character": 6,
          "line": 4
        },
        "start": {
          "character": 4,
          "line": 4
        }
      }
    }
  },
  "id": 20
}
<- {
  "jsonrpc": "2.0",
  "id": 20,
  "result": {
    "label": "Uppercase",
    "kind": 22,
    "deprecated": false,
    "preselect": true,
    "sortText": "ffffffef",
    "filterText": "Uppercase",
    "textEdit": {
      "newText": "Uppercase",
      "insert": {
        "start": {
          "line": 4,
          "character": 4
        },
        "end": {
          "line": 4,
          "character": 6
        }
      },
      "replace": {
        "start": {
          "line": 4,
          "character": 4
        },
        "end": {
          "line": 4,
          "character": 6
        }
      }
    },
    "additionalTextEdits": []
  }
}
<- {
  "additionalTextEdits": [],
  "deprecated": false,
  "filterText": "Uppercase",
  "kind": 22,
  "label": "Uppercase",
  "preselect": true,
  "sortText": "ffffffef",
  "textEdit": {
    "insert": {
      "end": {
        "character": 6,
        "line": 4
      },
      "start": {
        "character": 4,
        "line": 4
      }
    },
    "newText": "Uppercase",
    "replace": {
      "end": {
        "character": 6,
        "line": 4
      },
      "start": {
        "character": 4,
        "line": 4
      }
    }
  }
}
```

Neovim (and presumably Visual Studio Code) must be papering over the difference.
